"""The book file: one SQLite database with numbered schema versions.

Design notes
------------
* The schema version is ``PRAGMA user_version``.  Opening an old book never
  changes it; ``Store.migrate()`` applies one step per version, each in its own
  transaction together with its version bump.
* Connections run in autocommit mode (``isolation_level=None``) and every
  operation opens an explicit transaction, so DDL and DML are atomic alike.
* ``sqlite3`` exceptions never escape: they become ``ConflictError``.

Huge amounts
------------
The schema says ``minor INTEGER`` and SQLite integers are 64-bit, but Money may
be any size (``Money(10**30, "USD")``).  Column names and types stay exactly as
specified.  A value that fits in int64 is stored as a plain INTEGER (so books
built by hand or by older versions read back unchanged, and ``SUM`` still works
on them); a value outside int64 is stored as the TEXT ``big:<decimal digits>``.
That text is not a well-formed number, so the INTEGER column affinity leaves it
alone (a bare digit string would be silently turned into a lossy REAL).  Reading
turns either form back into an exact ``int``.  The same encoding is used for
``budgets.minor`` and ``recurring.max_count``.
"""
import contextlib
import json
import os
import re
import sqlite3
import threading
from dataclasses import dataclass, field
from datetime import date, timedelta

from tallybook.accounts import Chart, ROOTS, account_type, valid_path
from tallybook.currency import CURRENCIES, RateTable, currency as _currency, is_date
from tallybook.dates import format_date, parse_date
from tallybook.errors import (ConflictError, NotFoundError, TallybookError,
                              ValidationError)
from tallybook.ledger import Ledger, LedgerError
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, format_minor

LATEST_VERSION = 4

_BUSY_SECONDS = 5
_INT64_MIN = -(2 ** 63)
_INT64_MAX = 2 ** 63 - 1
_BIG = "big:"
_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_NAME_CHARS = re.compile(r"[A-Za-z0-9_-]+")
_CHUNK = 500


# ---------------------------------------------------------------------------
# results
# ---------------------------------------------------------------------------
@dataclass
class BulkAdd:
    added: list = field(default_factory=list)
    skipped: list = field(default_factory=list)


@dataclass
class ImportOutcome:
    added: list = field(default_factory=list)
    duplicates: list = field(default_factory=list)
    errors: list = field(default_factory=list)


# ---------------------------------------------------------------------------
# small helpers
# ---------------------------------------------------------------------------
def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _enc_int(n):
    if _INT64_MIN <= n <= _INT64_MAX:
        return n
    return "%s%d" % (_BIG, n)


def _dec_int(v):
    if isinstance(v, int) and not isinstance(v, bool):
        return v
    if isinstance(v, str) and v.startswith(_BIG):
        return int(v[len(_BIG):])
    raise ValueError("not an integer amount: %r" % (v,))


def _damaged(message):
    return ConflictError("damaged book: %s" % message)


def _map_error(exc):
    text = str(exc)
    if "locked" in text.lower() or "busy" in text.lower():
        return ConflictError("database is locked by another writer: %s" % text)
    return ConflictError("database error: %s" % text)


def _day(text):
    try:
        return parse_date(text)
    except TallybookError:
        raise _damaged("bad date %r" % (text,))


def _opt_day(text):
    return None if text is None else _day(text)


def _money(minor, cur):
    try:
        return Money(_dec_int(minor), cur)
    except (TallybookError, ValueError):
        raise _damaged("bad amount %r %r" % (minor, cur))


def _text(value, what):
    if not isinstance(value, str):
        raise ValidationError("%s must be text" % what)
    return value


def _seg_key(path):
    return path.split(":")


def _query_mod():
    from tallybook import query
    return query


def _rules_mod():
    from tallybook import rules
    return rules


def _csv_mod():
    from tallybook import csvimport
    return csvimport


def _journal_mod():
    from tallybook import journal
    return journal


def _budgets_mod():
    from tallybook import budgets
    return budgets


def _recurring_mod():
    from tallybook import recurring
    return recurring


def _nonneg(value, what):
    if not _is_int(value) or value < 0:
        raise ValidationError("%s must be a whole number of at least 0" % what)
    return value


def _sql_int(n):
    return max(_INT64_MIN, min(_INT64_MAX, n))


# ---------------------------------------------------------------------------
# schema and migrations
# ---------------------------------------------------------------------------
class _StepFailed(Exception):
    pass


def _step_1(c):
    c.execute("CREATE TABLE accounts (path TEXT PRIMARY KEY, type TEXT NOT NULL, currency TEXT, "
              "opened TEXT, note TEXT NOT NULL DEFAULT '')")
    c.execute("CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, "
              "payee TEXT NOT NULL, narration TEXT NOT NULL DEFAULT '', cleared INTEGER NOT NULL DEFAULT 1)")
    c.execute("CREATE TABLE postings (id INTEGER PRIMARY KEY AUTOINCREMENT, "
              "tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, "
              "seq INTEGER NOT NULL, account TEXT NOT NULL REFERENCES accounts(path), "
              "minor INTEGER NOT NULL, currency TEXT NOT NULL)")
    c.execute("CREATE INDEX transactions_date ON transactions (date, id)")
    c.execute("CREATE INDEX postings_tx ON postings (tx_id, seq)")


def _step_2(c):
    bad = c.execute("SELECT count(*) FROM transactions WHERE cleared IS NULL OR cleared NOT IN (0, 1) "
                    "OR typeof(cleared) NOT IN ('integer')").fetchone()[0]
    if bad:
        raise _StepFailed("%d transaction(s) have a cleared value that is not 0 or 1" % bad)
    c.execute("CREATE TABLE tags (tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, "
              "tag TEXT NOT NULL, PRIMARY KEY (tx_id, tag))")
    c.execute("ALTER TABLE transactions ADD COLUMN flag TEXT NOT NULL DEFAULT '*'")
    c.execute("ALTER TABLE postings ADD COLUMN note TEXT NOT NULL DEFAULT ''")
    c.execute("UPDATE transactions SET flag = CASE cleared WHEN 1 THEN '*' ELSE '!' END")


def _clean_code(value):
    if not isinstance(value, str):
        value = "" if value is None else str(value)
    return value.strip().upper()


def _is_code(text):
    return len(text) == 3 and text.isascii() and text.isalpha()


def _step_3(c):
    c.execute("CREATE TABLE rates (src TEXT NOT NULL, dst TEXT NOT NULL, on_date TEXT NOT NULL, "
              "rate_text TEXT NOT NULL, PRIMARY KEY (src, dst, on_date))")
    c.execute("ALTER TABLE accounts ADD COLUMN closed TEXT")
    updates = []
    for path, cur in c.execute("SELECT path, currency FROM accounts").fetchall():
        if cur is None:
            continue
        clean = _clean_code(cur)
        if clean == "":
            updates.append((None, path))
        elif _is_code(clean):
            if clean != cur:
                updates.append((clean, path))
        else:
            raise _StepFailed("account %s has the currency %r, which is not a currency code" % (path, cur))
    for clean, path in updates:
        c.execute("UPDATE accounts SET currency = ? WHERE path = ?", (clean, path))
    changes = []
    for (cur,) in c.execute("SELECT DISTINCT currency FROM postings").fetchall():
        clean = _clean_code(cur)
        if not _is_code(clean):
            raise _StepFailed("a posting has the currency %r, which is not a currency code" % (cur,))
        if clean != cur:
            changes.append((clean, cur))
    for clean, cur in changes:
        c.execute("UPDATE postings SET currency = ? WHERE currency = ?", (clean, cur))


def _step_4(c):
    c.execute("CREATE TABLE budgets (pattern TEXT NOT NULL, period_kind TEXT NOT NULL, minor INTEGER NOT NULL, "
              "currency TEXT NOT NULL, start_date TEXT NOT NULL, PRIMARY KEY (pattern, period_kind))")
    c.execute("CREATE TABLE recurring (name TEXT PRIMARY KEY, schedule TEXT NOT NULL, template TEXT NOT NULL, "
              "start_date TEXT NOT NULL, end_date TEXT, max_count INTEGER, materialized_through TEXT)")
    c.execute("CREATE TABLE rules (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL)")
    c.execute("CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)")
    c.execute("CREATE TABLE import_keys (key TEXT PRIMARY KEY, "
              "tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE)")


_STEPS = {1: _step_1, 2: _step_2, 3: _step_3, 4: _step_4}


# ---------------------------------------------------------------------------
# recurring template <-> JSON (kept here so storage does not need export.py)
# ---------------------------------------------------------------------------
def _template_to_json(tx):
    postings = []
    for p in tx.postings:
        amount = None
        if p.amount is not None:
            amount = {"minor": p.amount.minor, "currency": p.amount.currency}
        postings.append({"account": p.account, "amount": amount, "note": p.note})
    return json.dumps({
        "date": format_date(tx.date) if is_date(tx.date) else None,
        "payee": tx.payee, "narration": tx.narration, "flag": tx.flag,
        "tags": list(tx.tags), "id": tx.id, "postings": postings,
    }, sort_keys=True)


def _template_from_json(text):
    try:
        raw = json.loads(text)
        postings = []
        for p in raw["postings"]:
            amount = p["amount"]
            if amount is not None:
                amount = Money(amount["minor"], amount["currency"])
            postings.append(Posting(p["account"], amount, p["note"]))
        return Transaction(_opt_day(raw["date"]), raw["payee"], raw["narration"], postings,
                           tuple(raw["tags"]), raw["flag"], raw["id"])
    except ConflictError:
        raise
    except (ValueError, KeyError, TypeError, TallybookError):
        raise _damaged("unreadable recurring template")


# ---------------------------------------------------------------------------
# the store
# ---------------------------------------------------------------------------
class Store:
    """An open book file."""

    def __init__(self, conn, path):
        self._conn = conn
        self._path = path
        self._lock = threading.RLock()
        self._closed = False

    # -- opening -----------------------------------------------------------
    @classmethod
    def open(cls, path, create=False):
        try:
            given = os.fspath(path)
        except TypeError:
            raise ValidationError("the book path must be text or a path object")
        if isinstance(given, bytes):
            given = os.fsdecode(given)
        if given == "":
            raise NotFoundError("no such database: '' (run `tallybook init`)")
        full = os.path.abspath(given)
        if os.path.isdir(full):
            raise ConflictError("%s is a directory, not a book" % given)
        if not os.path.exists(full):
            if not create:
                raise NotFoundError("no such database: %s (run `tallybook init`)" % given)
            parent = os.path.dirname(full)
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % parent)
        conn = None
        try:
            conn = sqlite3.connect(full, timeout=_BUSY_SECONDS, isolation_level=None,
                                   check_same_thread=False)
            conn.execute("PRAGMA foreign_keys = ON")
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            tables = conn.execute("SELECT count(*) FROM sqlite_master WHERE type IN ('table', 'view') "
                                  "AND name NOT LIKE 'sqlite_%'").fetchone()[0]
        except sqlite3.Error as exc:
            if conn is not None:
                conn.close()
            raise ConflictError("%s is not a tallybook book: %s" % (given, exc))
        if version > LATEST_VERSION:
            conn.close()
            raise ConflictError("database is at version %d, newer than this tallybook (version %d)"
                                % (version, LATEST_VERSION))
        if version == 0 and tables:
            conn.close()
            raise ConflictError("%s is a database but not a tallybook book (no version marker)" % given)
        store = cls(conn, given)
        if version == 0 and create:
            try:
                store.migrate()
            except BaseException:
                store.close()
                raise
        return store

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def __repr__(self):
        return "<Store %r%s>" % (self._path, " closed" if self._closed else "")

    def close(self):
        with self._lock:
            if not self._closed:
                self._closed = True
                try:
                    self._conn.close()
                except sqlite3.Error:
                    pass

    # -- plumbing ----------------------------------------------------------
    def _live(self):
        if self._closed:
            raise ConflictError("the book is closed")
        return self._conn

    @property
    def version(self):
        with self._lock:
            conn = self._live()
            try:
                return conn.execute("PRAGMA user_version").fetchone()[0]
            except sqlite3.Error as exc:
                raise _map_error(exc)

    @staticmethod
    def _require_current(conn):
        v = conn.execute("PRAGMA user_version").fetchone()[0]
        if v < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)
        if v > LATEST_VERSION:
            raise ConflictError("database is at version %d, newer than this tallybook (version %d)"
                                % (v, LATEST_VERSION))

    @contextlib.contextmanager
    def _tx(self, write=False):
        """A transaction on the current-version book; rolls back on any error."""
        with self._lock:
            conn = self._live()
            try:
                conn.execute("BEGIN IMMEDIATE" if write else "BEGIN")
            except sqlite3.Error as exc:
                raise _map_error(exc)
            try:
                self._require_current(conn)
                yield conn
                conn.execute("COMMIT")
            except BaseException as exc:
                try:
                    conn.execute("ROLLBACK")
                except sqlite3.Error:
                    pass
                if isinstance(exc, sqlite3.Error):
                    raise _map_error(exc) from None
                raise

    # -- migration -----------------------------------------------------------
    def migrate(self):
        applied = []
        with self._lock:
            conn = self._live()
            while True:
                try:
                    v = conn.execute("PRAGMA user_version").fetchone()[0]
                except sqlite3.Error as exc:
                    raise _map_error(exc)
                if v > LATEST_VERSION:
                    raise ConflictError("database is at version %d, newer than this tallybook (version %d)"
                                        % (v, LATEST_VERSION))
                if v == LATEST_VERSION:
                    return applied
                n = v + 1
                try:
                    conn.execute("BEGIN IMMEDIATE")
                    try:
                        again = conn.execute("PRAGMA user_version").fetchone()[0]
                        if again == v:
                            _STEPS[n](conn)
                            conn.execute("PRAGMA user_version = %d" % n)
                        conn.execute("COMMIT")
                    except BaseException:
                        try:
                            conn.execute("ROLLBACK")
                        except sqlite3.Error:
                            pass
                        raise
                except (sqlite3.Error, _StepFailed, OverflowError) as exc:
                    raise ConflictError("migration to version %d failed: %s" % (n, exc)) from None
                if again == v:
                    applied.append(n)

    # -- loading rows --------------------------------------------------------
    def _account_rows(self, c):
        rows = c.execute("SELECT path, type, currency, opened, note, closed FROM accounts").fetchall()
        rows.sort(key=lambda r: _seg_key(r[0]))
        out = []
        for path, kind, cur, opened, note, closed in rows:
            out.append(Account(path, kind, cur, _opt_day(opened), _opt_day(closed),
                               "" if note is None else note))
        return out

    def _chart(self, c):
        chart = Chart()
        for acc in self._account_rows(c):
            try:
                made = chart.add(acc.path)
            except TallybookError:
                raise _damaged("invalid account path %r" % (acc.path,))
            made.currency = acc.currency
            made.opened = acc.opened
            made.closed = acc.closed
            made.note = acc.note
        return chart

    def _rate_table(self, c):
        table = RateTable()
        for src, dst, on, text in c.execute("SELECT src, dst, on_date, rate_text FROM rates"):
            try:
                table.set(src, dst, text, _day(on))
            except ConflictError:
                raise
            except TallybookError:
                raise _damaged("bad rate %s -> %s on %s" % (src, dst, on))
        return table

    def _hydrate(self, c, rows):
        ids = [r[0] for r in rows]
        postings = {}
        tags = {}
        for i in range(0, len(ids), _CHUNK):
            chunk = ids[i:i + _CHUNK]
            marks = ",".join("?" * len(chunk))
            for tx_id, account, minor, cur, note in c.execute(
                    "SELECT tx_id, account, minor, currency, note FROM postings WHERE tx_id IN (%s) "
                    "ORDER BY tx_id, seq, id" % marks, chunk):
                postings.setdefault(tx_id, []).append(Posting(account, _money(minor, cur), note))
            for tx_id, tag in c.execute("SELECT tx_id, tag FROM tags WHERE tx_id IN (%s)" % marks, chunk):
                tags.setdefault(tx_id, []).append(tag)
        out = []
        for tx_id, day, payee, narration, flag in rows:
            out.append(Transaction(_day(day), payee, narration, postings.get(tx_id, []),
                                   tuple(sorted(set(tags.get(tx_id, ())))), flag, tx_id))
        return out

    _TX_COLUMNS = "SELECT id, date, payee, narration, flag FROM transactions"

    def _all_transactions(self, c):
        return self._hydrate(c, c.execute(self._TX_COLUMNS + " ORDER BY date, id").fetchall())

    def _one_transaction(self, c, tx_id):
        if not _is_int(tx_id):
            raise ValidationError("a transaction id must be a whole number")
        if not _INT64_MIN <= tx_id <= _INT64_MAX:
            raise NotFoundError("no transaction %s" % (tx_id,))
        rows = c.execute(self._TX_COLUMNS + " WHERE id = ?", (tx_id,)).fetchall()
        if not rows:
            raise NotFoundError("no transaction %s" % (tx_id,))
        return self._hydrate(c, rows)[0]

    # -- accounts ------------------------------------------------------------
    @staticmethod
    def _filters(type, under, currency, include_closed):
        if type is not None and (not isinstance(type, str) or type not in ROOTS.values()):
            raise ValidationError("unknown account type %r: use asset, liability, equity, income or expense"
                                  % (type,))
        if under is not None and not valid_path(under):
            raise ValidationError("invalid account path %r" % (under,))
        if currency is not None and not isinstance(currency, str):
            raise ValidationError("currency must be text")

        def keep(acc):
            if type is not None and acc.type != type:
                return False
            if under is not None and acc.path != under and not acc.path.startswith(under + ":"):
                return False
            if currency is not None and acc.currency != currency:
                return False
            if not include_closed and acc.closed is not None:
                return False
            return True
        return keep

    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        keep = self._filters(type, under, currency, include_closed)
        with self._tx() as c:
            return [a for a in self._account_rows(c) if keep(a)]

    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        return len(self.accounts(type, under, currency, include_closed))

    def _stored_account(self, c, path):
        for acc in self._account_rows(c):
            if acc.path == path:
                return acc
        raise NotFoundError("no such account: %s" % (path,))

    def get_account(self, path):
        with self._tx() as c:
            return self._stored_account(c, path)

    def chart(self):
        with self._tx() as c:
            return self._chart(c)

    @staticmethod
    def _insert_account(c, acc):
        c.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) VALUES (?,?,?,?,?,?)",
                  (acc.path, acc.type, acc.currency,
                   None if acc.opened is None else format_date(acc.opened), acc.note,
                   None if acc.closed is None else format_date(acc.closed)))

    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        with self._tx(write=True) as c:
            chart = self._chart(c)
            made = chart.add(path, type, currency, opened, note)
            stored = Account(made.path, made.type, made.currency, made.opened, None, made.note)
            self._insert_account(c, stored)
            return stored

    def close_account(self, path, on):
        with self._tx(write=True) as c:
            self._stored_account(c, path)
            chart = self._chart(c)
            chart.close(path, on)
            late = c.execute("SELECT 1 FROM postings p JOIN transactions t ON t.id = p.tx_id "
                             "WHERE p.account = ? AND t.date > ? LIMIT 1", (path, format_date(on))).fetchone()
            if late:
                raise ConflictError("cannot close %s on %s: it has postings after that day"
                                    % (path, format_date(on)))
            c.execute("UPDATE accounts SET closed = ? WHERE path = ?", (format_date(on), path))
            return self._stored_account(c, path)

    def set_account_note(self, path, note):
        _text(note, "note")
        with self._tx(write=True) as c:
            self._stored_account(c, path)
            c.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path))
            return self._stored_account(c, path)

    def delete_account(self, path):
        with self._tx(write=True) as c:
            self._stored_account(c, path)
            used = c.execute("SELECT 1 FROM postings WHERE account = ? LIMIT 1", (path,)).fetchone()
            if used:
                raise ConflictError("account %s has postings and cannot be deleted" % path)
            c.execute("DELETE FROM accounts WHERE path = ?", (path,))

    # -- transactions ----------------------------------------------------------
    @staticmethod
    def _next_id(c):
        seq = 0
        has_seq = c.execute("SELECT 1 FROM sqlite_master WHERE name = 'sqlite_sequence'").fetchone()
        if has_seq:
            row = c.execute("SELECT seq FROM sqlite_sequence WHERE name = 'transactions'").fetchone()
            if row and _is_int(row[0]):
                seq = row[0]
        top = c.execute("SELECT COALESCE(MAX(id), 0) FROM transactions").fetchone()[0]
        return max(seq, top) + 1

    def _validate_batch(self, c, led, items):
        """items: [(index, tx)]; returns the stored transactions with fresh ids."""
        next_id = self._next_id(c)
        stored = []
        for index, tx in items:
            try:
                if not isinstance(tx, Transaction):
                    raise LedgerError("not a transaction: %r" % (tx,))
                probe = Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, next_id)
                stored.append(led.add(probe))
            except TallybookError as exc:
                exc.detail["index"] = index
                raise
            next_id += 1
        return stored

    def _insert_transactions(self, c, stored, keys=None):
        known = {r[0] for r in c.execute("SELECT path FROM accounts")}
        for tx in stored:
            for p in tx.postings:
                if p.account not in known:
                    # a posting to a parent that only exists implicitly: store it so the
                    # foreign key holds (the parent keeps no currency, dates or note)
                    self._insert_account(c, Account(p.account, account_type(p.account)))
                    known.add(p.account)
            c.execute("INSERT INTO transactions (id, date, payee, narration, cleared, flag) VALUES (?,?,?,?,?,?)",
                      (tx.id, format_date(tx.date), tx.payee, tx.narration,
                       1 if tx.flag == "*" else 0, tx.flag))
            c.executemany("INSERT INTO postings (tx_id, seq, account, minor, currency, note) VALUES (?,?,?,?,?,?)",
                          [(tx.id, i, p.account, _enc_int(p.amount.minor), p.amount.currency, p.note)
                           for i, p in enumerate(tx.postings)])
            c.executemany("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", [(tx.id, t) for t in tx.tags])
        if keys:
            for tx, key in zip(stored, keys):
                if key is not None:
                    c.execute("INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (key, tx.id))

    def add_transaction(self, tx):
        with self._tx(write=True) as c:
            led = Ledger(self._chart(c), self._rate_table(c))
            stored = self._validate_batch(c, led, [(0, tx)])
            self._insert_transactions(c, stored)
            return stored[0]

    def add_transactions(self, txs, keys=None):
        txs = list(txs)
        if keys is not None:
            keys = list(keys)
            if len(keys) != len(txs) or not all(isinstance(k, str) for k in keys):
                raise ValidationError("keys must be one text per transaction")
        with self._tx(write=True) as c:
            led = Ledger(self._chart(c), self._rate_table(c))
            skipped = []
            items = []
            item_keys = []
            seen = set()
            for i, tx in enumerate(txs):
                if keys is not None:
                    key = keys[i]
                    if key in seen or c.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone():
                        skipped.append(i)
                        continue
                    seen.add(key)
                    item_keys.append(key)
                items.append((i, tx))
            stored = self._validate_batch(c, led, items)
            self._insert_transactions(c, stored, item_keys if keys is not None else None)
            return BulkAdd(added=stored, skipped=skipped)

    def _compile_query(self, query, chart_source):
        """Returns None for 'everything', else a Query."""
        mod = _query_mod()
        if query is None:
            return None
        if isinstance(query, mod.Query):
            return None if query.is_empty else query
        if not isinstance(query, str):
            raise ValidationError("a query must be text or a parsed Query")
        if query.strip() == "":
            return None
        return mod.parse_query(query, chart_source())

    def transactions(self, query=None, limit=None, offset=0):
        if limit is not None:
            _nonneg(limit, "limit")
        _nonneg(offset, "offset")
        with self._tx() as c:
            q = self._compile_query(query, lambda: self._chart(c))
            if q is None:
                rows = c.execute(self._TX_COLUMNS + " ORDER BY date, id LIMIT ? OFFSET ?",
                                 (-1 if limit is None else _sql_int(limit), _sql_int(offset))).fetchall()
                return self._hydrate(c, rows)
            found = [t for t in self._all_transactions(c) if q.matches(t)]
            end = None if limit is None else offset + limit
            return found[offset:end]

    def count_transactions(self, query=None):
        with self._tx() as c:
            q = self._compile_query(query, lambda: self._chart(c))
            if q is None:
                return c.execute("SELECT count(*) FROM transactions").fetchone()[0]
            return sum(1 for t in self._all_transactions(c) if q.matches(t))

    def has_import_key(self, key):
        _text(key, "key")
        with self._tx() as c:
            return c.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone() is not None

    def get_transaction(self, id):
        with self._tx() as c:
            return self._one_transaction(c, id)

    def delete_transaction(self, id):
        with self._tx(write=True) as c:
            tx = self._one_transaction(c, id)
            # by hand: books built by old versions (or by hand) may lack the cascades
            c.execute("DELETE FROM postings WHERE tx_id = ?", (id,))
            c.execute("DELETE FROM tags WHERE tx_id = ?", (id,))
            c.execute("DELETE FROM import_keys WHERE tx_id = ?", (id,))
            c.execute("DELETE FROM transactions WHERE id = ?", (id,))
            return tx

    def ledger(self):
        with self._tx() as c:
            led = Ledger(self._chart(c), self._rate_table(c))
            for tx in self._all_transactions(c):
                led._store(tx)
            return led

    # -- rates ---------------------------------------------------------------
    def set_rate(self, src, dst, rate_text, on):
        with self._tx(write=True) as c:
            RateTable().set(src, dst, rate_text, on)
            c.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?,?,?,?)",
                      (src, dst, format_date(on), rate_text))

    def remove_rate(self, src, dst, on):
        with self._tx(write=True) as c:
            _currency(src)
            _currency(dst)
            if not is_date(on):
                from tallybook.currency import CurrencyError
                raise CurrencyError("not a date: %r" % (on,))
            cur = c.execute("DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?",
                            (src, dst, format_date(on)))
            if cur.rowcount == 0:
                raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, format_date(on)))

    def rate_rows(self):
        with self._tx() as c:
            rows = c.execute("SELECT src, dst, on_date, rate_text FROM rates "
                             "ORDER BY src, dst, on_date").fetchall()
            return [(s, d, _day(o), t) for s, d, o, t in rows]

    def rate_table(self):
        with self._tx() as c:
            return self._rate_table(c)

    # -- budgets ---------------------------------------------------------------
    def add_budget(self, budget):
        Budget = _budgets_mod().Budget
        if not isinstance(budget, Budget):
            raise ValidationError("not a budget: %r" % (budget,))
        with self._tx(write=True) as c:
            old = c.execute("SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?",
                            (budget.pattern, budget.period_kind)).fetchone()
            if old:
                raise ConflictError("there is already a %s budget for %s" % (budget.period_kind, budget.pattern))
            c.execute("INSERT INTO budgets (pattern, period_kind, minor, currency, start_date) VALUES (?,?,?,?,?)",
                      (budget.pattern, budget.period_kind, _enc_int(budget.amount.minor),
                       budget.amount.currency, format_date(budget.start)))

    def remove_budget(self, pattern, period_kind):
        with self._tx(write=True) as c:
            cur = c.execute("DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind))
            if cur.rowcount == 0:
                raise NotFoundError("no %s budget for %s" % (period_kind, pattern))

    def budgets(self):
        Budget = _budgets_mod().Budget
        with self._tx() as c:
            rows = c.execute("SELECT pattern, period_kind, minor, currency, start_date FROM budgets "
                             "ORDER BY pattern, period_kind").fetchall()
            out = []
            for pattern, kind, minor, cur, start in rows:
                try:
                    out.append(Budget(pattern, kind, _money(minor, cur), _day(start)))
                except ConflictError:
                    raise
                except TallybookError:
                    raise _damaged("bad budget %s %s" % (pattern, kind))
            return out

    # -- recurring -------------------------------------------------------------
    def add_recurring(self, rec):
        Recurring = _recurring_mod().Recurring
        if not isinstance(rec, Recurring):
            raise ValidationError("not a recurring item: %r" % (rec,))
        with self._tx(write=True) as c:
            if c.execute("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)).fetchone():
                raise ConflictError("recurring item %s already exists" % rec.name)
            c.execute("INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count, "
                      "materialized_through) VALUES (?,?,?,?,?,?,NULL)",
                      (rec.name, str(rec.schedule), _template_to_json(rec.template), format_date(rec.start),
                       None if rec.end is None else format_date(rec.end),
                       None if rec.count is None else _enc_int(rec.count)))

    def remove_recurring(self, name):
        with self._tx(write=True) as c:
            cur = c.execute("DELETE FROM recurring WHERE name = ?", (name,))
            if cur.rowcount == 0:
                raise NotFoundError("no recurring item %s" % (name,))

    def _recurring_rows(self, c):
        Recurring = _recurring_mod().Recurring
        rows = c.execute("SELECT name, schedule, template, start_date, end_date, max_count, "
                         "materialized_through FROM recurring ORDER BY name").fetchall()
        out = []
        for name, schedule, template, start, end, count, through in rows:
            try:
                rec = Recurring(name, schedule, _template_from_json(template), _day(start), _opt_day(end),
                                None if count is None else _dec_int(count))
            except ConflictError:
                raise
            except (TallybookError, ValueError):
                raise _damaged("bad recurring item %s" % (name,))
            out.append((rec, _opt_day(through)))
        return out

    def recurring(self):
        with self._tx() as c:
            return [rec for rec, _ in self._recurring_rows(c)]

    def materialized_through(self, name):
        with self._tx() as c:
            row = c.execute("SELECT materialized_through FROM recurring WHERE name = ?", (name,)).fetchone()
            if row is None:
                raise NotFoundError("no recurring item %s" % (name,))
            return _opt_day(row[0])

    def materialize(self, upto=None, today=None):
        for value, what in ((upto, "upto"), (today, "today")):
            if value is not None and not is_date(value):
                raise ValidationError("%s must be a date" % what)
        if upto is None and today is None:
            raise ValidationError("materialize needs upto or today")
        horizon = min(d for d in (upto, today) if d is not None)
        rmod = _recurring_mod()
        with self._tx(write=True) as c:
            items = []
            rows = self._recurring_rows(c)
            for pos, (rec, through) in enumerate(rows):
                first = rec.start
                if through is not None:
                    if through >= date.max:
                        continue
                    first = max(first, through + timedelta(days=1))
                if horizon < first:
                    continue
                for day in rmod.occurrences(rec, first, horizon):
                    items.append((day, rec.name, pos, rec))
            items.sort(key=lambda it: (it[0], it[1], it[2]))
            made = [(i, rmod.instantiate(rec, day)) for i, (day, _n, _p, rec) in enumerate(items)]
            led = Ledger(self._chart(c), self._rate_table(c))
            stored = self._validate_batch(c, led, made)
            self._insert_transactions(c, stored)
            for rec, through in rows:
                if through is None or horizon > through:
                    c.execute("UPDATE recurring SET materialized_through = ? WHERE name = ?",
                              (format_date(horizon), rec.name))
            return stored

    # -- rules, settings, profiles ----------------------------------------------
    def set_rules(self, text):
        _text(text, "rules")
        _rules_mod().parse_rules(text)
        with self._tx(write=True) as c:
            c.execute("INSERT OR REPLACE INTO rules (id, body) VALUES (1, ?)", (text,))

    def rules_text(self):
        with self._tx() as c:
            row = c.execute("SELECT body FROM rules WHERE id = 1").fetchone()
            return "" if row is None else row[0]

    def rules(self):
        text = self.rules_text()
        try:
            return _rules_mod().parse_rules(text)
        except TallybookError as exc:
            raise _damaged("stored rules do not parse: %s" % exc)

    def get_setting(self, key, default=None):
        with self._tx() as c:
            row = c.execute("SELECT value FROM settings WHERE key = ?", (key,)).fetchone() \
                if isinstance(key, str) else None
            return default if row is None else row[0]

    def set_setting(self, key, value):
        if not isinstance(key, str) or key == "":
            raise ValidationError("a setting key must be non-empty text")
        _text(value, "a setting value")
        with self._tx(write=True) as c:
            c.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", (key, value))

    def delete_setting(self, key):
        with self._tx(write=True) as c:
            if isinstance(key, str):
                c.execute("DELETE FROM settings WHERE key = ?", (key,))

    def settings(self):
        with self._tx() as c:
            return {k: v for k, v in c.execute("SELECT key, value FROM settings ORDER BY key")}

    @staticmethod
    def _profile_key(name):
        if not isinstance(name, str) or not _NAME.fullmatch(name):
            raise ValidationError("invalid profile name %r: use letters, digits, _ and -" % (name,))
        return "profile." + name

    def set_profile(self, name, text):
        key = self._profile_key(name)
        _text(text, "a profile")
        _csv_mod().parse_profile(text)
        self.set_setting(key, text)

    def profile_text(self, name):
        if not isinstance(name, str) or not _NAME.fullmatch(name):
            raise NotFoundError("no such profile: %s" % (name,))
        value = self.get_setting("profile." + name)
        if value is None:
            raise NotFoundError("no such profile: %s" % (name,))
        return value

    def profiles(self):
        return [k[len("profile."):] for k in self.settings() if k.startswith("profile.")]

    def remove_profile(self, name):
        self.profile_text(name)
        self.delete_setting("profile." + name)

    # -- CSV import ---------------------------------------------------------------
    def import_csv(self, text, profile, apply_rules=True):
        cmod = _csv_mod()
        if not isinstance(text, str):
            raise ValidationError("the CSV must be text")
        with self._tx(write=True) as c:
            if isinstance(profile, cmod.ImportProfile):
                prof = profile
            elif isinstance(profile, str):
                if _NAME_CHARS.fullmatch(profile):
                    row = c.execute("SELECT value FROM settings WHERE key = ?", ("profile." + profile,)).fetchone()
                    if row is None:
                        raise NotFoundError("no such profile: %s" % profile)
                    prof = cmod.parse_profile(row[0])
                else:
                    prof = cmod.parse_profile(profile)
            else:
                raise ValidationError("a profile must be a name, profile text or an ImportProfile")
            ruleset = None
            if apply_rules:
                row = c.execute("SELECT body FROM rules WHERE id = 1").fetchone()
                if row is not None and row[0].strip():
                    ruleset = _rules_mod().parse_rules(row[0])
            existing = self._all_transactions(c)
            result = cmod.import_csv(text, prof, ruleset, existing)
            if result.errors:
                return ImportOutcome([], list(result.duplicates), list(result.errors))

            def base_key(tx):
                for p in tx.postings:
                    if p.account == prof.account and p.amount is not None:
                        return "%s|%s|%s|%d %s" % (format_date(tx.date), tx.payee, prof.account,
                                                    p.amount.minor, p.amount.currency)
                return None

            counts = {}
            for tx in result.duplicates:
                k = base_key(tx)
                counts[k] = counts.get(k, 0) + 1
            keys = []
            used = set()
            for tx in result.transactions:
                k = base_key(tx)
                n = counts.get(k, 0) + 1
                while True:
                    full = "%s|%d" % (k, n)
                    if full not in used and not c.execute("SELECT 1 FROM import_keys WHERE key = ?",
                                                          (full,)).fetchone():
                        break
                    n += 1
                counts[k] = n
                used.add(full)
                keys.append(full)
            led = Ledger(self._chart(c), self._rate_table(c))
            stored = self._validate_batch(c, led, list(enumerate(result.transactions)))
            self._insert_transactions(c, stored, keys)
            return ImportOutcome(stored, list(result.duplicates), [])

    # -- journals -------------------------------------------------------------------
    def journal(self):
        jmod = _journal_mod()
        with self._tx() as c:
            rates = [(s, d, _day(o), t) for s, d, o, t in
                     c.execute("SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date")]
            return jmod.Journal(accounts=self._account_rows(c), rates=rates,
                                transactions=self._all_transactions(c))

    def load_journal(self, journal):
        jmod = _journal_mod()
        if not isinstance(journal, jmod.Journal):
            raise ValidationError("not a journal: %r" % (journal,))
        with self._tx(write=True) as c:
            chart = self._chart(c)
            rates = self._rate_table(c)
            for acc in journal.accounts:
                made = chart.add(acc.path, acc.type, acc.currency, acc.opened, acc.note)
                if acc.closed is not None:
                    chart.close(acc.path, acc.closed)
                self._insert_account(c, Account(made.path, made.type, made.currency, made.opened,
                                                made.closed, made.note))
            for src, dst, on, text in journal.rates:
                rates.set(src, dst, text, on)
                c.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?,?,?,?)",
                          (src, dst, format_date(on), text))
            led = Ledger(chart, rates)
            stored = self._validate_batch(c, led, list(enumerate(journal.transactions)))
            self._insert_transactions(c, stored)
            return stored

    # -- health, backup, status ---------------------------------------------------------
    def check(self):
        problems = []
        with self._tx() as c:
            try:
                rows = c.execute("PRAGMA integrity_check").fetchall()
            except sqlite3.DatabaseError as exc:
                return ["integrity check failed: %s" % exc]
            if [r[0] for r in rows] != ["ok"]:
                problems.extend("integrity check failed: %s" % r[0] for r in rows)
            for pid, tx_id in c.execute("SELECT p.id, p.tx_id FROM postings p WHERE NOT EXISTS "
                                        "(SELECT 1 FROM transactions t WHERE t.id = p.tx_id)"):
                problems.append("posting %s refers to missing transaction %s" % (pid, tx_id))
            for tx_id, tag in c.execute("SELECT g.tx_id, g.tag FROM tags g WHERE NOT EXISTS "
                                        "(SELECT 1 FROM transactions t WHERE t.id = g.tx_id)"):
                problems.append("tag %s refers to missing transaction %s" % (tag, tx_id))
            for key, tx_id in c.execute("SELECT k.key, k.tx_id FROM import_keys k WHERE NOT EXISTS "
                                        "(SELECT 1 FROM transactions t WHERE t.id = k.tx_id)"):
                problems.append("import key %s refers to missing transaction %s" % (key, tx_id))
            for (tx_id,) in c.execute("SELECT t.id FROM transactions t WHERE NOT EXISTS "
                                      "(SELECT 1 FROM postings p WHERE p.tx_id = t.id)"):
                problems.append("transaction %s has no postings" % tx_id)
            for pid, tx_id, account in c.execute("SELECT p.id, p.tx_id, p.account FROM postings p WHERE NOT EXISTS "
                                                 "(SELECT 1 FROM accounts a WHERE a.path = p.account)"):
                problems.append("posting %s of transaction %s is on account %s, which is not stored"
                                % (pid, tx_id, account))
            sums = {}
            for pid, tx_id, minor, cur in c.execute(
                    "SELECT p.id, p.tx_id, p.minor, p.currency FROM postings p WHERE EXISTS "
                    "(SELECT 1 FROM transactions t WHERE t.id = p.tx_id)").fetchall():
                try:
                    value = _dec_int(minor)
                except ValueError:
                    problems.append("posting %s has an unreadable amount %r" % (pid, minor))
                    continue
                per = sums.setdefault(tx_id, {})
                per[cur] = per.get(cur, 0) + value
            for tx_id in sorted(sums):
                off = sorted((cur, v) for cur, v in sums[tx_id].items() if v != 0)
                if off:
                    shown = []
                    for cur, v in off:
                        try:
                            shown.append("%s %s" % (cur, format_minor(v, cur)))
                        except TallybookError:
                            shown.append("%s %d" % (cur, v))
                    problems.append("transaction %s does not balance: %s" % (tx_id, ", ".join(shown)))
        return sorted(problems)

    def backup(self, dest):
        try:
            given = os.fspath(dest)
        except TypeError:
            raise ValidationError("the backup destination must be text or a path object")
        if isinstance(given, bytes):
            given = os.fsdecode(given)
        if given == "":
            raise NotFoundError("no such directory for the backup: ''")
        full = os.path.abspath(given)
        with self._lock:
            self._live()
            with self._tx():
                pass
            if os.path.lexists(full):
                raise ConflictError("backup destination %s already exists" % given)
            parent = os.path.dirname(full)
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % parent)
            tmp = "%s.part-%d" % (full, os.getpid())
            target = None
            try:
                target = sqlite3.connect(tmp)
                self._conn.backup(target)
                target.close()
                target = None
                try:
                    os.link(tmp, full)
                except FileExistsError:
                    raise ConflictError("backup destination %s already exists" % given)
                except OSError:
                    if os.path.lexists(full):
                        raise ConflictError("backup destination %s already exists" % given)
                    os.rename(tmp, full)
            except sqlite3.Error as exc:
                raise _map_error(exc)
            except OSError as exc:
                raise ConflictError("cannot write the backup: %s" % exc)
            finally:
                if target is not None:
                    target.close()
                try:
                    os.unlink(tmp)
                except OSError:
                    pass

    def info(self):
        with self._tx() as c:
            counts = {}
            for name in ("accounts", "transactions", "postings", "rates", "budgets", "recurring"):
                counts[name] = c.execute("SELECT count(*) FROM %s" % name).fetchone()[0]
            version = c.execute("PRAGMA user_version").fetchone()[0]
        out = {"path": self._path, "version": version}
        out.update(counts)
        return out

